const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
export function structureSettings(value={}){return {type:['bridge','tunnel'].includes(value?.type)?value.type:'none',length:clamp(Number(value?.length)||30,12,120),clearance:clamp(Number(value?.clearance)||6,4.5,12),height:Number.isFinite(value?.height)?clamp(value.height,4.5,80):null,grade:clamp(Number(value?.grade)||6,3,15),approach:clamp(Number(value?.approach)||1.15,1,2),offset:clamp(Number(value?.offset)||0,-80,80),bridgeStyle:value?.bridgeStyle==='concrete'?'concrete':'steel',tunnelStyle:value?.tunnelStyle==='box'?'box':'arch',...(Number.isFinite(value?.anchorProgress)&&['bridge','tunnel'].includes(value?.type)?{anchorProgress:clamp(value.anchorProgress,0,1)}:{})};}
